def statuts_initiaux(apps, schema_editor):
    """Statut déduit des données existantes ; rien d'autre ne change (accès, publication vitrine)."""
    Promotion = apps.get_model("agenda", "Promotion")
    Inscription = apps.get_model("evaluation", "Inscription")
    JournalStatut = apps.get_model("evaluation", "JournalStatut")
    Inscription.objects.filter(statut="terminee").update(statut="validee")
    aujourd_hui = datetime.date.today()
    for p in Promotion.objects.all():
        if not p.active:
            statut = "archivee"
        elif p.publiee_vitrine:
            statut = "inscriptions"
        elif p.date_debut <= aujourd_hui and Inscription.objects.filter(promotion=p).exclude(statut="abandon").exists():
            statut = "en_cours"
        else:
            statut = "planifiee"
        p.statut = statut
        p.save(update_fields=["statut"])
        JournalStatut.objects.create(promotion=p, vers=statut, motif="Statut initial déduit des données existantes")


def annuler(apps, schema_editor):
    apps.get_model("evaluation", "Inscription").objects.filter(
        statut__in=["validee", "non_validee"]).update(statut="terminee")
    apps.get_model("evaluation", "Inscription").objects.filter(
        statut__in=["admise", "confirmee"]).update(statut="en_cours")


